// docs/plugins/quickstart.md 기반: 도구 카드를 앱에서 원본 UI로 보여 주기
import { defineTool } from '@deepseek-ai/dsh-tools'
import { toolCard } from './tool-card.js'
import { weatherView } from './view.js'

ctx.tools.register(defineTool({
  name: 'weather_forecast',
  output: {
    schema,
    render: (args, value) => [{ type: 'text', text: summary(value) }],
    presentationMeta: toolCard((args, value) => weatherView(value)),
  },
}))
// 설치: dsh plugin --profile web add /절대경로/플러그인
